/// <summary>
/// Set fields on the <c>PSAProjInvoiceHeaderTmp</c> record from corresponding regular tables.
/// </summary>
protected void populatePSAProjInvoiceHeaderTmp()
{
    next populatePSAProjInvoiceHeaderTmp();

    HcmWorker avaWorker = HcmWorker::find(hcmWorker::userId2Worker(ProjInvoiceTable::find(projInvoiceJour.ProjInvoiceProjId).CreatedBy));

    tmpPSAProjInvoiceHeader.AVAWSTName  = avaWorker.avaPersonName();
    tmpPSAProjInvoiceHeader.AVAWSTMail  = avaWorker.email();
    tmpPSAProjInvoiceHeader.AVAWSTPhone = avaWorker.phone() + ' ' + avaWorker.phoneLocal();

    tmpPSAProjInvoiceHeader.AVACashDiscTxt      = CashDisc::txt(projInvoiceJour.CashDiscCode, projInvoiceJour.LanguageId);
    tmpPSAProjInvoiceHeader.AVAPaymentCondition = PaymTerm::txt(projInvoiceJour.Payment, projInvoiceJour.LanguageId);

    tmpPSAProjInvoiceHeader.CustName            = projInvoiceJour.DeliveryName ? projInvoiceJour.DeliveryName : custTable.avaName();

}

/// <summary>
/// Initializes the project invoice line based on an invoice employee line.
/// </summary>
/// <param name = "_projInvoiceEmpl">The invoice employee line used when initializing the project invoice line.</param>
protected void initFromProjInvoiceEmpl(ProjInvoiceEmpl _projInvoiceEmpl)
{
    next initFromProjInvoiceEmpl(_projInvoiceEmpl);

    tmpPSAProjInvoice.TransDate = _projInvoiceEmpl.TransDate;
}

